# Route optimization script v2
import json

def optimize(routes, drones, objective='min_time'):
    assignments = []
    for route in routes:
        best = min((d for d in drones if d['status'] == 'available'), key=lambda d: d['max_range_km'], default=None)
        if best:
            assignments.append({'route_id': route['route_id'], 'drone_id': best['drone_id']})
    return assignments

